mapper.select:
SELECT *
FROM shopwizard.tCatProdChnl
INNER JOIN shopwizard.tCatProd ON shopwizard.tCatProd.ProdCode = shopwizard.tCatProdChnl.ProdCode


        AND (shopwizard.tCatProd.ProdCode = #{pProdCode} OR shopwizard.tCatProd.ShopProdCode = #{pProdCode})

    AND shopwizard.tCatProd.CateCode = #{pCateCode}
    AND shopwizard.tCatProd.ShopCode = #{pShopCode}
    AND ShopProdCode = #{pShopProdCode}
    AND shopwizard.tCatProd.ProdName LIKE CONCAT('%',#{pProdName},'%')
    AND shopwizard.tCatProd.SaleYn = #{pSaleYn}
    AND ChnlCode = #{pChnlCode}

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tCatProdChnl
INNER JOIN shopwizard.tCatProd ON shopwizard.tCatProd.ProdCode = shopwizard.tCatProdChnl.ProdCode


        AND (shopwizard.tCatProd.ProdCode = #{pProdCode} OR shopwizard.tCatProd.ShopProdCode = #{pProdCode})

    AND shopwizard.tCatProd.CateCode = #{pCateCode}
    AND shopwizard.tCatProd.ShopCode = #{pShopCode}
    AND ShopProdCode = #{pShopProdCode}
    AND shopwizard.tCatProd.ProdName LIKE CONCAT('%',#{pProdName},'%')
    AND shopwizard.tCatProd.SaleYn = #{pSaleYn}
    AND ChnlCode = #{pChnlCode}
